import React from 'react';
import {AbsoluteFill, Composition, Easing, Img, interpolate, registerRoot, useCurrentFrame, useVideoConfig} from 'remotion';

/**
 * Standalone Remotion entry: original PNG assets are embedded below.
 * Render: npx remotion render JourneyTreeEvolution.tsx JourneyEvolution output.mp4
 * 1920x1080, 30 fps, 8 seconds. Edit CONFIG for timings, colors and text.
 * Text switches only while entirely occluded by the interface.
 */
export const CONFIG = {
  fps: 30, duration: 8, width: 1920, height: 1080,
  background: '#F7F8FC', accent: '#1755E7', text: '#1B2435', problemColor: '#BB4854', solutionColor: '#087B60',
  viewport: {x: 739, y: 60, width: 442, height: 960},
  textStartX: 120, textEndX: 1320, hiddenSwitchX: 750,
  intro: [0, 0.65], problemEntry: [1, 1.55], travel: [2.3, 5.7],
  scan: [2.45, 5.5],
  problem: ['Difficult to access', 'specific steps in a', 'linear journey.'],
  solution: ['Flexible, stage-based', 'navigation at your', 'own pace.'],
};
const clamp = {extrapolateLeft: 'clamp', extrapolateRight: 'clamp'} as const;
const ease = Easing.bezier(0.4, 0, 0.2, 1);
const out = Easing.bezier(0.16, 1, 0.3, 1);
export const JourneyEvolution: React.FC = () => {
  const frame = useCurrentFrame();
  const {fps} = useVideoConfig();
  const t = frame / fps;
  const ramp = (times: number[], easing = ease) => interpolate(t, times, [0, 1], {...clamp, easing});
  const intro = ramp(CONFIG.intro, out);
  const entry = ramp(CONFIG.problemEntry, out);
  const travel = ramp(CONFIG.travel);
  const scan = ramp(CONFIG.scan);
  const textX = CONFIG.textStartX - 30 * (1-entry) + (CONFIG.textEndX-CONFIG.textStartX)*travel;
  // At x=750 both text variants fit behind the opaque x=739..1181 interface.
  // No visible crossfade: the content changes while fully occluded.
  const isSolution = textX >= CONFIG.hiddenSwitchX;
  const lines = isSolution ? CONFIG.solution : CONFIG.problem;
  const v = CONFIG.viewport;
  const boundary = scan * v.width;
  const lineOpacity = interpolate(t, [2.45, 2.60, 5.5, 5.8], [0,1,1,0], clamp);
  const imageStyle: React.CSSProperties = {width:'100%',height:'100%',objectFit:'contain',display:'block'};
  return <AbsoluteFill style={{backgroundColor:CONFIG.background}}>
    <svg width={CONFIG.width} height={CONFIG.height} style={{position:'absolute',inset:0}}>
      <g opacity={entry} transform={`translate(${textX},405)`} fontFamily="Arial, sans-serif">
        <text y={20} fill={isSolution ? CONFIG.solutionColor : CONFIG.problemColor}
          fontSize={20} fontWeight={700} letterSpacing={3.2}>
          {isSolution ? 'SOLUTION' : 'PROBLEM'}
        </text>
        {lines.map((line, i) => <text key={i} y={80+i*53.32} fontSize={43}
          letterSpacing={-1.2} fill={CONFIG.text}>{line}</text>)}
      </g>
    </svg>
    <div style={{position:'absolute',left:v.x,top:v.y,width:v.width,height:v.height,opacity:intro,transform:`scale(${0.98+0.02*intro})`,background:CONFIG.background,boxShadow:'0 12px 36px rgba(27,36,53,0.10)'}}>
      <Img src={INITIAL_IMAGE} style={imageStyle}/>
      <div style={{position:'absolute',inset:0,background:CONFIG.background,maskImage:scan===1?'none':`linear-gradient(to right, black ${boundary-4}px, transparent ${boundary+4}px)`,WebkitMaskImage:scan===1?'none':`linear-gradient(to right, black ${boundary-4}px, transparent ${boundary+4}px)`,opacity:scan===0?0:1}}>
        <Img src={REFINED_IMAGE} style={imageStyle}/>
      </div>
      <div style={{position:'absolute',top:0,bottom:0,left:boundary-1.5,width:3,background:CONFIG.accent,opacity:lineOpacity}}/>
    </div>
  </AbsoluteFill>;
};
const Root = () => <Composition id="JourneyEvolution" component={JourneyEvolution} durationInFrames={Math.round(CONFIG.duration*CONFIG.fps)} fps={CONFIG.fps} width={CONFIG.width} height={CONFIG.height}/>;

// Original screenshots, preserved without modification.
const INITIAL_IMAGE = 'data:image/png;base64,';
const REFINED_IMAGE = 'data:image/png;base64,';

registerRoot(Root);
